const idb = {
 async db():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const r=indexedDB.open('proyek-cair-offline',1);r.onupgradeneeded=()=>r.result.createObjectStore('queue',{keyPath:'client_key'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});},
 async all():Promise<any[]>{const d=await this.db();return new Promise((res,rej)=>{const r=d.transaction('queue').objectStore('queue').getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error);});},
 async put(v:any){const d=await this.db();return new Promise<void>((res,rej)=>{const r=d.transaction('queue','readwrite').objectStore('queue').put(v);r.onsuccess=()=>res();r.onerror=()=>rej(r.error);});},
 async del(k:string){const d=await this.db();return new Promise<void>((res,rej)=>{const r=d.transaction('queue','readwrite').objectStore('queue').delete(k);r.onsuccess=()=>res();r.onerror=()=>rej(r.error);});}
};
const queueOwnerId=(row:any):string|null=>row?.user_id||row?.payload?.created_by||row?.payload?.reported_by||null;
const getOwnedQueue=async(userId:string)=>userId?(await idb.all()).filter(row=>queueOwnerId(row)===userId):[];
const isTransientNetworkError=(error:any)=>{
 if(!error||error.code||typeof error.status==='number')return false;
 if(typeof navigator!=='undefined'&&!navigator.onLine)return true;
 const message=String(error.message||error).toLowerCase();
 return (error.name==='TypeError'&&/fetch|network/.test(message))||/failed to fetch|network request failed|networkerror|load failed|connection (reset|refused|lost)|timed? ?out/.test(message);
};
const persistOfflineEntry=async(kind:'PROGRESS'|'SAFETY',payload:any,key:string,userId:string)=>{
 await idb.put({client_key:key,kind,payload,user_id:userId,workspace_id:payload.workspace_id,project_id:payload.project_id,queued_at:new Date().toISOString()});
 return getOwnedQueue(userId);
};
